const center = penpot.viewport.center;
const steps = 12;
for (let i = 0; i < steps; i++) {
  const rect = penpot.createRectangle();
  const size = 20 + (i * 5);
  rect.resize(size, size);
  const angle = (i * 30) * (Math.PI / 180);
  const radius = 50 + (i * 10);
  rect.x = center.x + Math.cos(angle) * radius - (size / 2);
  rect.y = center.y + Math.sin(angle) * radius - (size / 2);
  rect.rotation = i * 30;
  const hue = (i * 30) % 360;
  rect.fills = [{fillColor: `hsl(${hue}, 70%, 50%)`}];
}

const steps = ['Étape 1', 'Étape 2', 'Étape 3', 'Étape 4'];
const startY = 100;
const spacing = 80;

const line = penpot.createRectangle();
line.resize(4, 280);
line.x = 148;
line.y = startY;
line.fills = [{fillColor: '#95A5A6'}];

for (let i = 0; i < steps.length; i++) {
  const dot = penpot.createEllipse();
  dot.resize(20, 20);
  dot.x = 140;
  dot.y = startY + (i * spacing);
  dot.fills = [{fillColor: i < 2 ? '#2ECC71' : '#95A5A6'}];
  dot.strokes = [{strokeColor: '#FFFFFF', strokeWidth: 3}];

  const label = penpot.createText(steps[i]);
  label.x = 170;
  label.y = startY + (i * spacing) + 2;
  label.fontSize = 16;
  label.fills = [{fillColor: '#2C3E50'}];
}

const data = [65, 45, 80, 30, 90];
const maxHeight = 150;
const barWidth = 40;
const spacing = 10;
const startX = 100;
const baseY = 300;

for (let i = 0; i < data.length; i++) {
  const height = (data[i] / 100) * maxHeight;
  const bar = penpot.createRectangle();
  bar.resize(barWidth, height);
  bar.x = startX + (i * (barWidth + spacing));
  bar.y = baseY - height;
  bar.fills = [{fillColor: '#3498DB'}];

  const value = penpot.createText(data[i].toString());
  value.x = bar.x + 10;
  value.y = bar.y - 20;
  value.fontSize = 12;
  value.fills = [{fillColor: '#2C3E50'}];
}

